css:
#dyn-message-theme[data-theme="message-brushed"] {
  --chrome: var(--primary, #f4f6fb);
  --gold: var(--secondary, #e8c35a);
  --navy: var(--name-box, #06102a);
  --plate: color-mix(in srgb, var(--navy) 68%, #000);
  --left-hue: 0deg;
  --sky-hue: 0deg;
  --text-brush-hue: 0deg;
  --foil-grain: url("data:image/png;base64,");
  background: #06102a;
  overflow: hidden;
}
#dyn-message-theme[data-theme="message-brushed"] .defs,
#dyn-message-theme[data-theme="message-brushed"] .sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
}
#dyn-message-theme[data-theme="message-brushed"] .hd {
  position: absolute;
  inset: 0;
  overflow: hidden;
}
#dyn-message-theme[data-theme="message-brushed"] .bg {
  position: absolute;
  inset: 0;
  z-index: 0;
  overflow: hidden;
  opacity: 0;
}
#dyn-message-theme[data-theme="message-brushed"] .sky {
  position: absolute;
  inset: -10%;
  background-color: #06102a;
  background-image: url("data:image/jpeg;base64,");
  background-size: cover;
  background-position: center;
  transform-origin: 30% 50%;
  will-change: transform;
  filter: hue-rotate(var(--sky-hue, 0deg));
  animation: hd-sky-zoom 14s ease-in-out infinite alternate;
}
#dyn-message-theme[data-theme="message-brushed"] .bg-brush {
  position: absolute;
  left: -5.47%;
  top: -9.72%;
  width: 73.63%;
  height: 119.44%;
  background-image: url("data:image/webp;base64,");
  background-size: 100% 100%;
  background-repeat: no-repeat;
  pointer-events: none;
  transform-origin: 30% 50%;
  will-change: transform;
  filter: hue-rotate(var(--left-hue, 0deg));
  animation: hd-brush-zoom 14s ease-in-out infinite alternate;
}
#dyn-message-theme[data-theme="message-brushed"] .lights {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 28% 18% at 16% 6%, color-mix(in srgb, #fff 16%, transparent), transparent 70%),
    radial-gradient(ellipse 36% 22% at 88% 8%, color-mix(in srgb, #4d7cff 14%, transparent), transparent 72%);
  pointer-events: none;
  mix-blend-mode: screen;
}
#dyn-message-theme[data-theme="message-brushed"] .flare {
  position: absolute;
  width: 22cqw;
  height: 22cqw;
  border-radius: 50%;
  background: radial-gradient(circle, color-mix(in srgb, #fff 30%, transparent) 0%, transparent 68%);
  pointer-events: none;
  opacity: 0;
  mix-blend-mode: screen;
}
#dyn-message-theme[data-theme="message-brushed"] .flare-a { left: 8cqw; top: -4cqh; }
#dyn-message-theme[data-theme="message-brushed"] .flare-b { right: 10cqw; top: 2cqh; width: 16cqw; height: 16cqw; }
#dyn-message-theme[data-theme="message-brushed"] .dust {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 3;
  overflow: hidden;
}
#dyn-message-theme[data-theme="message-brushed"] .dust i {
  position: absolute;
  border-radius: 50%;
  background: color-mix(in srgb, var(--gold) 82%, #fff);
  box-shadow: 0 0 0.45cqh color-mix(in srgb, var(--gold) 55%, transparent);
  pointer-events: none;
  opacity: 0;
}
#dyn-message-theme[data-theme="message-brushed"] .vignette {
  position: absolute;
  inset: 0;
  background: radial-gradient(120% 90% at 50% 46%, transparent 58%, rgba(0, 0, 0, 0.28) 100%);
  pointer-events: none;
}
#dyn-message-theme[data-theme="message-brushed"] .card {
  --cut: 5.6cqh;
  --frame-clip: polygon(var(--cut) 0, 100% 0, 100% calc(100% - var(--cut)), calc(100% - var(--cut)) 100%, 0 100%, 0 var(--cut));
  position: absolute;
  left: 5cqw;
  top: 8.2cqh;
  width: 35.6cqw;
  height: 78.4cqh;
  z-index: 6;
  overflow: visible;
  opacity: 0;
  transform: translateX(-6cqw) scale(0.95);
}
#dyn-message-theme[data-theme="message-brushed"] .card-rim {
  position: relative;
  z-index: 2;
  width: 100%;
  height: 100%;
  padding: 0.5cqh;
  background: #000;
  clip-path: var(--frame-clip);
}
#dyn-message-theme[data-theme="message-brushed"] .card-inner {
  --cut: 5.1cqh;
  position: relative;
  width: 100%;
  height: 100%;
  padding: 0.95cqh;
  background:
    linear-gradient(165deg, #fff8d2 0%, #f4d56f 18%, var(--gold) 46%, #8d6a14 78%, #f3d27c 100%);
  box-shadow:
    inset 0 0.16cqh 0 rgba(255, 255, 255, 0.7),
    inset 0 -0.16cqh 0 rgba(55, 35, 0, 0.42),
    inset 0.14cqh 0 0 rgba(255, 255, 255, 0.28),
    inset -0.14cqh 0 0 rgba(55, 35, 0, 0.3);
  clip-path: var(--frame-clip);
}
#dyn-message-theme[data-theme="message-brushed"] .card img {
  position: relative;
  z-index: 1;
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center top;
  background: #1a2338;
  --cut: 4.05cqh;
  clip-path: var(--frame-clip);
}
#dyn-message-theme[data-theme="message-brushed"] .card .frame-halo {
  position: absolute;
  inset: 0;
  z-index: 0;
  background: color-mix(in srgb, var(--gold) 88%, #fff);
  clip-path: var(--frame-clip);
  filter:
    blur(0.55cqh)
    drop-shadow(0 0 0.9cqh #fff)
    drop-shadow(0 0 1.6cqh color-mix(in srgb, var(--gold) 95%, #fff))
    drop-shadow(0 0 3cqh color-mix(in srgb, var(--gold) 60%, transparent));
  pointer-events: none;
  opacity: 0.95;
}
#dyn-message-theme[data-theme="message-brushed"] .card .frame-bloom {
  position: absolute;
  z-index: 3;
  width: 8.6cqw;
  height: 8.6cqw;
  border-radius: 50%;
  background: radial-gradient(circle, #fff 0%, color-mix(in srgb, var(--gold) 75%, #fff) 26%, transparent 70%);
  mix-blend-mode: screen;
  pointer-events: none;
  opacity: 0.7;
}
#dyn-message-theme[data-theme="message-brushed"] .card .frame-bloom.tl { top: -2.2cqh; left: -1.6cqw; }
#dyn-message-theme[data-theme="message-brushed"] .card .frame-bloom.tr { top: -2cqh; right: -1.4cqw; }
#dyn-message-theme[data-theme="message-brushed"] .card .frame-bloom.br { bottom: -2.2cqh; right: -1.6cqw; }
#dyn-message-theme[data-theme="message-brushed"] .card .frame-bloom.bl { bottom: -1.8cqh; left: -1.2cqw; width: 5.4cqw; height: 5.4cqw; }
#dyn-message-theme[data-theme="message-brushed"] .copy {
  position: absolute;
  left: 36.4cqw;
  right: 3.6cqw;
  top: 6.4cqh;
  bottom: 6cqh;
  z-index: 5;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: stretch;
  min-width: 0;
  padding: 1cqh 1cqw;
  overflow: visible;
}
#dyn-message-theme[data-theme="message-brushed"] .copy-lockup {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 0;
  padding: 0 1.2cqw;
  overflow: visible;
  transform: translateY(-4.2cqh) rotate(-6deg);
  transform-origin: 50% 55%;
}
#dyn-message-theme[data-theme="message-brushed"] .paint-wrap {
  --stroke: none;
  --stroke-pos: center;
  position: relative;
  width: 200%;
  height: 10.4cqh;
  flex: 0 0 auto;
  align-self: center;
  overflow: visible;
  pointer-events: none;
  clip-path: inset(-80% 100% -80% -6%);
  filter: hue-rotate(var(--text-brush-hue, 0deg));
}
#dyn-message-theme[data-theme="message-brushed"] .paint-top {
  margin-bottom: -2.2cqh;
  transform: translateY(-1.6cqh);
  --stroke: url("data:image/webp;base64,");
  --stroke-pos: center bottom;
}
#dyn-message-theme[data-theme="message-brushed"] .paint-bot {
  position: absolute;
  left: 50%;
  top: 100%;
  z-index: 0;
  margin: 0;
  transform: translate(-50%, -18%);
  --stroke: url("data:image/webp;base64,");
  --stroke-pos: center top;
}
#dyn-message-theme[data-theme="message-brushed"] .brush-fill,
#dyn-message-theme[data-theme="message-brushed"] .brush-flare {
  position: absolute;
  inset: 0;
}
#dyn-message-theme[data-theme="message-brushed"] .brush-fill {
  background: var(--stroke) var(--stroke-pos, center) / contain no-repeat;
}
#dyn-message-theme[data-theme="message-brushed"] .brush-flare {
  -webkit-mask-image: var(--stroke);
  mask-image: var(--stroke);
  -webkit-mask-size: contain;
  mask-size: contain;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  -webkit-mask-position: var(--stroke-pos, center);
  mask-position: var(--stroke-pos, center);
  background: radial-gradient(ellipse 22% 80% at 50% 50%, rgba(255, 255, 255, 0.95) 0%, rgba(255, 236, 180, 0.5) 28%, transparent 70%);
  background-repeat: no-repeat;
  background-size: 38% 160%;
  background-position: -40% 50%;
  mix-blend-mode: screen;
  filter: blur(0.28cqh);
  opacity: 0;
}
#dyn-message-theme[data-theme="message-brushed"] .flecks {
  position: absolute;
  left: 8%;
  right: 8%;
  top: 28%;
  height: 36%;
  pointer-events: none;
}
#dyn-message-theme[data-theme="message-brushed"] .flecks b {
  position: absolute;
  width: 0.45cqh;
  height: 0.45cqh;
  border-radius: 50%;
  background: color-mix(in srgb, var(--gold) 85%, #fff);
  opacity: 0;
}
#dyn-message-theme[data-theme="message-brushed"] .flecks b:nth-child(1) { left: 12%; top: 18%; }
#dyn-message-theme[data-theme="message-brushed"] .flecks b:nth-child(2) { left: 28%; top: 62%; }
#dyn-message-theme[data-theme="message-brushed"] .flecks b:nth-child(3) { left: 46%; top: 30%; }
#dyn-message-theme[data-theme="message-brushed"] .flecks b:nth-child(4) { left: 64%; top: 70%; }
#dyn-message-theme[data-theme="message-brushed"] .flecks b:nth-child(5) { left: 78%; top: 22%; }
#dyn-message-theme[data-theme="message-brushed"] .flecks b:nth-child(6) { left: 90%; top: 54%; }
#dyn-message-theme[data-theme="message-brushed"] .line1,
#dyn-message-theme[data-theme="message-brushed"] .heroes {
  text-align: center;
  text-transform: uppercase;
  width: 100%;
  min-width: 0;
  max-width: 100%;
  overflow: visible;
}
#dyn-message-theme[data-theme="message-brushed"] .line1 {
  position: relative;
  min-height: 0;
  padding: 0.1cqh 0.6cqw 0.06em;
  font-family: Impact, "Arial Black", "Haettenschweiler", sans-serif;
  font-style: italic;
  font-weight: 400;
  font-size: 9.6cqh;
  letter-spacing: 0.02em;
  line-height: 0.85;
  color: var(--chrome);
  white-space: nowrap;
  text-shadow:
    0 0.12cqh 0 #fff,
    0 0.32cqh 0 color-mix(in srgb, var(--chrome) 50%, #8b90a0),
    0 0.22cqh 0.7cqh rgba(0, 0, 0, 0.78),
    0 0.5cqh 1.5cqh rgba(0, 0, 0, 0.72),
    0 0.85cqh 2.4cqh rgba(0, 0, 0, 0.48);
}
#dyn-message-theme[data-theme="message-brushed"] .line1 .word {
  position: relative;
  display: inline-block;
  opacity: 0;
  transform: translateX(1.4cqw) scale(1.1);
  margin: 0 0.06em;
}
#dyn-message-theme[data-theme="message-brushed"] .heroes {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  min-height: 0;
  margin-top: 0.11em;
  padding: 0.03em 1.2cqw 0;
  font-size: 15cqh;
}
#dyn-message-theme[data-theme="message-brushed"] .hero + .hero {
  margin-top: 0;
}
#dyn-message-theme[data-theme="message-brushed"] .hero {
  position: relative;
  display: flex;
  justify-content: center;
  overflow: visible;
  width: 100%;
  max-width: 100%;
  padding: 0 0.6cqw 0;
  clip-path: none;
  opacity: 0;
  transform: none;
  filter:
    drop-shadow(0 0.22cqh 0.55cqh rgba(0, 0, 0, 0.78))
    drop-shadow(0 0.5cqh 1.4cqh rgba(0, 0, 0, 0.7))
    drop-shadow(0 0.85cqh 2.2cqh rgba(0, 0, 0, 0.42));
}
#dyn-message-theme[data-theme="message-brushed"] .hero-fill {
  position: relative;
  display: inline-block;
  box-sizing: content-box;
  width: max-content;
  max-width: 100%;
  margin: 0 auto;
  text-align: center;
  padding: 0.04em 0.5em 0.03em 0.38em;
  font-size: inherit;
  font-family: "Rubik Wet Paint", "Permanent Marker", Impact, sans-serif;
  font-style: italic;
  font-weight: 400;
  line-height: 0.8;
  white-space: nowrap;
  overflow-wrap: normal;
  word-break: normal;
  overflow: visible;
  color: var(--gold);
  background-image:
    var(--foil-grain),
    repeating-linear-gradient(-18deg, transparent 0 0.16em, color-mix(in srgb, #3a2a05 22%, transparent) 0.16em 0.2em),
    repeating-linear-gradient(72deg, transparent 0 0.12em, color-mix(in srgb, #fff 26%, transparent) 0.12em 0.15em),
    linear-gradient(185deg, color-mix(in srgb, var(--gold) 62%, #fff) 0%, var(--gold) 36%, color-mix(in srgb, var(--gold) 58%, #6a5010) 70%, color-mix(in srgb, var(--gold) 84%, #fff) 100%);
  background-size: 0.55em 0.55em, 0.7em 0.7em, 0.42em 0.42em, 100% 100%;
  background-origin: padding-box;
  background-blend-mode: overlay, multiply, soft-light, normal;
  -webkit-box-decoration-break: clone;
  box-decoration-break: clone;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  filter: none;
}
#dyn-message-theme[data-theme="message-brushed"] .hero-fill::before,
#dyn-message-theme[data-theme="message-brushed"] .hero-fill::after {
  content: "";
  display: inline-block;
  width: 0.18em;
  height: 0;
}
#dyn-message-theme[data-theme="message-brushed"] .plate {
  --frame-clip: polygon(11.8% 0, 100% 0, 96.4% 72%, 88.2% 100%, 0 100%, 6.5% 19%);
  position: relative;
  align-self: center;
  width: max-content;
  max-width: 100%;
  margin-top: 5.6cqh;
  min-height: 13.8cqh;
  overflow: visible;
  opacity: 0;
  transform: scaleX(0.16);
}
#dyn-message-theme[data-theme="message-brushed"] .plate-svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
  z-index: 1;
  filter:
    drop-shadow(0 0 0.45cqh rgba(255, 255, 255, 0.55))
    drop-shadow(0 0 1.1cqh color-mix(in srgb, var(--gold) 70%, transparent))
    drop-shadow(0 0 1.8cqh rgba(77, 143, 255, 0.42));
}
#dyn-message-theme[data-theme="message-brushed"] .plate-stroke-black {
  fill: none;
  stroke: #000;
  stroke-width: 13;
  stroke-linejoin: miter;
  vector-effect: non-scaling-stroke;
}
#dyn-message-theme[data-theme="message-brushed"] .plate-fill {
  fill: var(--plate);
  stroke: none;
}
#dyn-message-theme[data-theme="message-brushed"] .plate-stroke-gold {
  fill: none;
  stroke: url(#hd-gold-emboss);
  stroke-width: 7;
  stroke-linejoin: miter;
  vector-effect: non-scaling-stroke;
}
#dyn-message-theme[data-theme="message-brushed"] .plate-flares {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  overflow: hidden;
  clip-path: var(--frame-clip);
}
#dyn-message-theme[data-theme="message-brushed"] .lf-streak {
  position: absolute;
  left: 2%;
  right: 2%;
  height: 1.8cqh;
  background: linear-gradient(90deg,
    transparent 0%,
    rgba(77, 143, 255, 0.08) 18%,
    rgba(77, 143, 255, 0.28) 36%,
    rgba(255, 255, 255, 0.45) 50%,
    rgba(232, 195, 90, 0.32) 64%,
    rgba(232, 195, 90, 0.08) 82%,
    transparent 100%);
  filter: blur(0.85cqh);
  mix-blend-mode: screen;
  opacity: 0;
}
#dyn-message-theme[data-theme="message-brushed"] .lf-streak.top { top: 6%; }
#dyn-message-theme[data-theme="message-brushed"] .lf-streak.bot { bottom: 6%; }
#dyn-message-theme[data-theme="message-brushed"] .lf-spike {
  position: absolute;
  top: 44%;
  width: 28%;
  height: 0.7cqh;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.4), rgba(126, 182, 255, 0.28), rgba(255, 224, 138, 0.3), transparent);
  filter: blur(0.7cqh);
  mix-blend-mode: screen;
  opacity: 0;
}
#dyn-message-theme[data-theme="message-brushed"] .lf-spike.l { left: -4%; }
#dyn-message-theme[data-theme="message-brushed"] .lf-spike.r { right: -4%; }
#dyn-message-theme[data-theme="message-brushed"] .lf-orb {
  position: absolute;
  width: 5.4cqw;
  height: 5.4cqw;
  border-radius: 50%;
  background:
    radial-gradient(circle, rgba(255, 255, 255, 0.7) 0%, rgba(255, 255, 255, 0.4) 12%, rgba(232, 195, 90, 0.28) 28%, rgba(77, 143, 255, 0.16) 50%, transparent 72%);
  filter: blur(0.55cqh);
  mix-blend-mode: screen;
  opacity: 0;
}
#dyn-message-theme[data-theme="message-brushed"] .lf-orb.tl { top: -1.2cqh; left: 3%; }
#dyn-message-theme[data-theme="message-brushed"] .lf-orb.tr { top: -1.3cqh; right: 2%; width: 6.4cqw; height: 6.4cqw; }
#dyn-message-theme[data-theme="message-brushed"] .lf-orb.br { bottom: -1.2cqh; right: 5%; }
#dyn-message-theme[data-theme="message-brushed"] .lf-orb.bl { bottom: -1cqh; left: 1%; width: 4.6cqw; height: 4.6cqw; }
#dyn-message-theme[data-theme="message-brushed"] .lf-ghost {
  position: absolute;
  border-radius: 50%;
  mix-blend-mode: screen;
  filter: blur(0.55cqh);
  opacity: 0;
}
#dyn-message-theme[data-theme="message-brushed"] .lf-ghost.a {
  top: 8%;
  left: 28%;
  width: 3.6cqw;
  height: 3.6cqw;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.4) 0%, rgba(77, 143, 255, 0.22) 35%, transparent 70%);
}
#dyn-message-theme[data-theme="message-brushed"] .lf-ghost.b {
  bottom: 6%;
  right: 24%;
  width: 3cqw;
  height: 3cqw;
  background: radial-gradient(circle, rgba(255, 236, 170, 0.4) 0%, rgba(232, 195, 90, 0.2) 40%, transparent 72%);
}
#dyn-message-theme[data-theme="message-brushed"] .name-box {
  position: relative;
  z-index: 3;
  height: 13.8cqh;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  padding: 0 4.8cqw;
  overflow: visible;
  background: transparent;
}
#dyn-message-theme[data-theme="message-brushed"] .name-box span {
  display: block;
  width: max-content;
  max-width: none;
  margin: 0;
  text-align: center;
  text-transform: uppercase;
  white-space: nowrap;
  font-family: Impact, "Arial Black", "Haettenschweiler", sans-serif;
  font-style: italic;
  font-weight: 400;
  font-size: 7cqh;
  letter-spacing: 0.06em;
  color: var(--chrome);
  line-height: 1;
  text-shadow:
    0 0.1cqh 0 #fff,
    0 0.35cqh 0 color-mix(in srgb, var(--chrome) 50%, #8b90a0);
  opacity: 0;
  transform: translateY(2cqh);
}
#dyn-message-theme[data-theme="message-brushed"].no-photo .card { display: none; }
#dyn-message-theme[data-theme="message-brushed"].no-photo .copy { left: 8cqw; right: 8cqw; }
#dyn-message-theme[data-theme="message-brushed"].no-copy .plate,
#dyn-message-theme[data-theme="message-brushed"].no-name .plate { display: none; }
#dyn-message-theme[data-theme="message-brushed"].no-line1 .line1 { display: none; }
#dyn-message-theme[data-theme="message-brushed"].no-hero .heroes,
#dyn-message-theme[data-theme="message-brushed"].no-hero .paint-wrap,
#dyn-message-theme[data-theme="message-brushed"].no-hero .flecks { display: none; }
#dyn-message-theme[data-theme="message-brushed"] .logo-slot,
#dyn-message-theme[data-theme="message-brushed"] .qr-slot {
  position: absolute;
  z-index: 8;
  width: 11cqw;
  min-width: 9cqh;
}
#dyn-message-theme[data-theme="message-brushed"] .logo-slot { top: 3.2cqh; left: 3cqw; }
#dyn-message-theme[data-theme="message-brushed"] .qr-slot { right: 3cqw; bottom: 3.4cqh; }
#dyn-message-theme[data-theme="message-brushed"].dyn-show-logo:not(.dyn-show-qr) .copy { top: 14cqh; }
#dyn-message-theme[data-theme="message-brushed"].dyn-show-qr:not(.dyn-show-logo) .copy { right: 18cqw; bottom: 12cqh; }
#dyn-message-theme[data-theme="message-brushed"].dyn-show-qr.dyn-show-logo .copy { top: 14cqh; right: 18cqw; bottom: 12cqh; }
#dyn-message-theme[data-theme="message-brushed"][data-photo-style="bw"] .card img { filter: grayscale(1) contrast(1.08); }
#dyn-message-theme[data-theme="message-brushed"][data-photo-style="color"] .card img { filter: contrast(1.04) saturate(1.06); }
#dyn-message-theme[data-theme="message-brushed"][data-photo-style="sepia"] .card img { filter: sepia(0.72) contrast(1.05); }

#dyn-message-theme[data-theme="message-brushed"].on .bg {
  animation: hd-fade 0.45s ease both;
