  visibility: hidden;
}
@keyframes hd-copy-out {
  from { opacity: 1; transform: none; filter: none; }
  to { opacity: 0; transform: translateY(-2.4cqh); filter: blur(4px); }
}
@keyframes hd-card-out {
  from { opacity: 1; transform: none; filter: none; }
  to { opacity: 0; transform: translateX(-5cqw) scale(0.96); filter: blur(6px); }
}

@keyframes hd-fade { from { opacity: 0; } to { opacity: 1; } }
@keyframes hd-sky-zoom {
  from { transform: scale(1); }
  to { transform: scale(1.14); }
}
@keyframes hd-brush-zoom {
  from { transform: scale(1); }
  to { transform: scale(1.3); }
}
@keyframes hd-bloom {
  0%, 100% { opacity: 0.72; }
  50% { opacity: 1; }
}
@keyframes hd-flare {
  0%, 78%, 100% { opacity: 0; transform: scale(0.86); }
  84% { opacity: 0.45; transform: scale(1); }
}
@keyframes hd-card-in {
  from { opacity: 0; transform: translateX(-6cqw) scale(0.95); filter: blur(4px); }
  78% { transform: translateX(0.4cqw) scale(1.015); filter: blur(0); }
  to { opacity: 1; transform: none; filter: none; }
}
@keyframes hd-card-fizz {
  from { opacity: 0; transform: translateY(5cqh) scale(0.92); }
  to { opacity: 1; transform: none; }
}
@keyframes hd-brush {
  from { clip-path: inset(-80% 100% -80% -6%); }
  to { clip-path: inset(-80% -6% -80% -6%); }
}
@keyframes hd-brush-flare {
  0% { background-position: -40% 50%; opacity: 0; }
  12% { opacity: 1; }
  40% { background-position: 140% 50%; opacity: 0; }
  100% { background-position: 140% 50%; opacity: 0; }
}
@keyframes hd-fleck {
  from { opacity: 0; transform: translate(0, 0) scale(0.4); }
  40% { opacity: 1; }
  to { opacity: 0; transform: translate(1.6cqw, -1.2cqh) scale(1); }
}
@keyframes hd-word {
  from { opacity: 0; transform: translateX(1.6cqw) scale(1.1); filter: brightness(1.8); }
  to { opacity: 1; transform: none; filter: none; }
}
@keyframes hd-word-fizz {
  from { opacity: 0; transform: translateY(3cqh) rotate(-5deg) scale(0.9); }
  to { opacity: 1; transform: none; }
}
@keyframes hd-hero {
  from { opacity: 0; transform: translateY(1.2cqh); }
  to { opacity: 1; transform: none; }
}
@keyframes hd-plate {
  from { opacity: 0; transform: scaleX(0.16); }
  to { opacity: 1; transform: none; }
}
@keyframes hd-name {
  from { opacity: 0; transform: translateY(2cqh); }
  to { opacity: 1; transform: none; }
}
@keyframes hd-lf-streak {
  0%, 100% { opacity: 0.1; filter: blur(1cqh); }
  50% { opacity: 0.38; filter: blur(0.75cqh); }
}
@keyframes hd-lf-spike {
  0%, 100% { opacity: 0.08; }
  50% { opacity: 0.28; }
}
@keyframes hd-lf-orb {
  0%, 100% { opacity: 0.12; transform: scale(0.86); }
  50% { opacity: 0.36; transform: scale(1.06); }
}
@keyframes hd-lf-ghost {
  0%, 100% { opacity: 0.08; transform: scale(0.9); }
  50% { opacity: 0.24; transform: scale(1.04); }
}
@keyframes hd-bloom-pulse {
  0%, 100% { opacity: 0.42; transform: scale(0.88); }
  50% { opacity: 1; transform: scale(1.12); }
}

